# Problem: #3041 Maximize Consecutive Elements in an Array After Modification
# Language: python3
# Submission Result: Submission Sent (Check LeetCode Profile)
# Auto-generated by LeetCode Agent

class Solution:
    def maxSelectedElements(self, nums: List[int]) -> int:
        nums.sort()
        ans, prev = 1, -inf
        prev_max = prev_max_1 = 1
        for x in nums:
            if x == prev:
                prev_max_1 = prev_max + 1
                ans = max(ans, prev_max_1)
                continue
            if x - prev > 2:
                prev_max = prev_max_1 = 1
            elif x == prev + 1:
                prev_max, prev_max_1 = prev_max + 1, prev_max_1 + 1
                ans = max(ans, prev_max, prev_max_1)
            else:
                prev_max, prev_max_1 = prev_max_1 + 1, 1
                ans = max(ans, prev_max)
            prev = x
        return ans